class Solution:
    def connectSticks(self, sticks: list[int]) -> int:
        arr = sticks[:]
        total = 0
        while len(arr) > 1:
            arr.sort()
            merged = arr[0] + arr[1]
            total += merged
            arr = arr[2:] + [merged]
        return total

